const body = $input.first().json.body ?? $input.first().json;
const records = body.records;
if (!Array.isArray(records) || records.length === 0) throw new Error('records must be a non-empty array');
const clean = records.map((r, i) => {
  const quantity = Number(r.quantity); const unit_price = Number(r.unit_price);
  if (!Number.isFinite(quantity) || !Number.isFinite(unit_price) || quantity < 0 || unit_price < 0) throw new Error(`Invalid quantity/unit_price in record ${i + 1}`);
  return { product: String(r.product ?? 'Unspecified product'), category: String(r.category ?? 'Uncategorized'), quantity, unit_price, revenue: quantity * unit_price };
});
const total_revenue = clean.reduce((s, r) => s + r.revenue, 0);
const units_sold = clean.reduce((s, r) => s + r.quantity, 0);
const byCategory = {}; for (const r of clean) byCategory[r.category] = (byCategory[r.category] ?? 0) + r.revenue;
return [{ json: { record_count: clean.length, total_revenue: Number(total_revenue.toFixed(2)), units_sold, average_revenue_per_record: Number((total_revenue / clean.length).toFixed(2)), revenue_by_category: byCategory, records: clean } }];
